log = repo.read("logs/service.log", missing_ok = True)
if log == None:
    fail("logs/service.log not found")

lines = log.split("\n")
hits = []
for i, l in enumerate(lines):
    if "ALERT" in l:
        hits.append(i)

if not hits:
    return {"found": False, "total_lines": len(lines)}

out = []
for i in hits:
    out.append({
        "alert_line_number": i + 1,
        "context": lines[max(0, i-1):i+2],
    })

return {"found": True, "total_lines": len(lines), "hits": out}
